-- Row level security is switched on with no policies at all, which denies every
-- request that it applies to. The server connects as the table owner and so
-- bypasses it entirely, while Supabase's public REST API, which does not, is
-- left with no way to read a single row. Without this, anyone holding the
-- project's publishable key could read the sign-in tables over HTTP.
ALTER TABLE public.icloud_account ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.icloud_jwks ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."icloud_oauthAccessToken" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."icloud_oauthClient" ENABLE ROW LEVEL SECURITY;
