ALTER TABLE public."icloud_oauthRefreshToken" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."icloud_oauthResource" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.icloud_passkey ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.icloud_session ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.icloud_user ENABLE ROW LEVEL SECURITY;
